BEGIN;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
DO $$DECLARE payload jsonb:=public.test_payload('2026-11-01'); r jsonb; plan uuid; rev jsonb; request uuid:=gen_random_uuid(); BEGIN
 r:=public.pilot_sales_target_command_v1(request,'save_draft',payload);plan:=(r->'plan'->>'id')::uuid;
 PERFORM public.test_assert(r->>'status'='committed' AND r->'plan'->>'state'='draft','saved draft not published');
 PERFORM public.test_assert(public.pilot_sales_target_command_v1(request,'save_draft',payload)=r,'identical retry receipt');
 PERFORM public.test_assert(public.pilot_sales_target_reconcile_v1(request)=r,'reconcile persisted receipt');
 PERFORM public.test_assert(public.pilot_sales_target_reconcile_v1(gen_random_uuid())->>'status'='not_found','absent request explicit');
 PERFORM public.test_rejected(format('SELECT public.pilot_sales_target_command_v1(%L,''save_draft'',%L::jsonb)',request,payload||'{"reason":"changed"}'),'payload mismatch rejected');
 PERFORM public.test_rejected(format('SELECT public.pilot_sales_target_command_v1(%L,''submit'',%L::jsonb)',gen_random_uuid(),payload||jsonb_build_object('planId',plan,'expectedVersion',0)),'stale expected version rejected');
 payload:=payload||jsonb_build_object('planId',plan,'expectedVersion',1);
 r:=public.pilot_sales_target_command_v1(gen_random_uuid(),'submit',payload);
 PERFORM public.test_assert(r->'plan'->>'state'='submitted' AND r->'plan'->>'version'='2','manager submits complete roster');
 PERFORM public.test_denied(format('SELECT public.pilot_sales_target_command_v1(%L,''approve_publish'',%L::jsonb)',gen_random_uuid(),jsonb_build_object('planId',plan,'expectedVersion',2)),'manager cannot self approve');
 PERFORM set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',true);
 PERFORM public.test_denied(format('SELECT public.pilot_sales_target_plan_v1(%L)',plan),'salesperson cannot see submitted plan');
 PERFORM set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
 PERFORM public.test_rejected(format('SELECT public.pilot_sales_target_command_v1(%L,''return'',%L::jsonb)',gen_random_uuid(),jsonb_build_object('planId',plan,'expectedVersion',2)),'return reason required');
 r:=public.pilot_sales_target_command_v1(gen_random_uuid(),'approve_publish',jsonb_build_object('planId',plan,'expectedVersion',2));
 PERFORM public.test_assert(r->'plan'->>'state'='published' AND r->'plan'->>'publishedBy'='10000000-0000-4000-8000-000000000002','Head alone sufficient');
 PERFORM set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',true);
 PERFORM public.test_assert(jsonb_array_length(public.pilot_sales_target_plan_v1(plan)->'lines')=3 AND NOT (public.pilot_sales_target_plan_v1(plan)?'auditEvents'),'salesperson own published lines only, no audit history');
 PERFORM public.test_assert(public.pilot_sales_dashboard_v3('2026-11-01','own',NULL,1,20)->'targets'->'po_order_value'->>'amount'='120.00','own published metric target');
 PERFORM set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
 rev:=public.pilot_sales_target_command_v1(gen_random_uuid(),'propose_revision',jsonb_build_object('planId',plan,'expectedVersion',3,'reason','Synthetic revision review'));
 PERFORM public.test_assert(rev->'plan'->>'id'<>plan::text AND rev->'plan'->>'state'='draft','published edit new draft');
 PERFORM public.test_assert(public.pilot_sales_target_plan_v1(plan)->>'state'='published','old remains active while revision draft');
 r:=public.pilot_sales_target_plan_v1((rev->'plan'->>'id')::uuid);
 PERFORM public.test_assert(r#>>'{auditEvents,0,operation}'='propose_revision' AND r#>>'{auditEvents,0,before,state}'='published' AND r#>>'{auditEvents,0,before,lines,0,amount}'='120.00' AND r#>>'{auditEvents,0,reason}'='Synthetic revision review','revision audit carries old published values and reason');
 PERFORM public.test_assert(r#>>'{auditEvents,0,actorName}'='Manager' AND r#>>'{auditEvents,0,occurredAt}' IS NOT NULL AND jsonb_array_length(r#>'{auditEvents,0,before,people}')=3 AND NOT ((r#>'{auditEvents,0,before}')?'baselineSnapshot'),'narrow audit actor/time/people without customer history');
 payload:=public.test_payload('2026-11-01')||jsonb_build_object('planId',rev->'plan'->>'id','expectedVersion',1,'lines',(SELECT jsonb_agg(line||'{"amount":"121.00"}'::jsonb) FROM jsonb_array_elements(public.test_lines())line));
 r:=public.pilot_sales_target_command_v1(gen_random_uuid(),'submit',payload);
 PERFORM set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
 r:=public.pilot_sales_target_command_v1(gen_random_uuid(),'approve_publish',jsonb_build_object('planId',r->'plan'->>'id','expectedVersion',2));
 PERFORM public.test_assert(r->'plan'->>'state'='published' AND public.pilot_sales_target_plan_v1(plan)->>'state'='superseded','executive alone approves atomic supersession');
 r:=public.pilot_sales_target_plan_v1((r->'plan'->>'id')::uuid);
 PERFORM public.test_assert(r#>>'{auditEvents,1,before,lines,0,amount}'='120.00' AND r#>>'{auditEvents,1,after,lines,0,amount}'='121.00' AND (r->>'auditEventsTruncated')::boolean=false,'audit exposes prior and changed values on reload');
 PERFORM set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000007',true);
 PERFORM public.test_denied(format('SELECT public.pilot_sales_target_plan_v1(%L)',r->>'id'),'unrelated manager cannot read audit');
END$$;
RESET ROLE;
SELECT public.test_assert((SELECT count(*) FROM private.sales_target_active)=9,'one active value per person/month/metric');
SELECT public.test_assert((SELECT count(*) FROM private.sales_target_events)=7,'complete create/submit/approve/revise/submit/supersede/approve audit');
SELECT public.test_rejected($q$UPDATE private.sales_target_lines SET amount=1 WHERE plan_id IN(SELECT id FROM private.sales_target_plans WHERE state='published')$q$,'published line immutable even owner');
SELECT public.test_rejected($q$UPDATE private.sales_target_events SET reason='tampered'$q$,'audit append only');
SELECT set_config('test.audit_plan',(SELECT id::text FROM private.sales_target_plans WHERE state='published'),true);
INSERT INTO private.sales_target_events(plan_id,request_id,operation,actor_id,after_state)
SELECT current_setting('test.audit_plan')::uuid,gen_random_uuid(),'save_draft','10000000-0000-4000-8000-000000000003',private.sales_target_plan_json_v1(current_setting('test.audit_plan')::uuid) FROM generate_series(1,101);
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
SELECT public.test_assert(jsonb_array_length(public.pilot_sales_target_plan_v1(current_setting('test.audit_plan')::uuid)->'auditEvents')=100 AND (public.pilot_sales_target_plan_v1(current_setting('test.audit_plan')::uuid)->>'auditEventsTruncated')::boolean,'latest 100 audit events bounded with honest truncation');
ROLLBACK;
SELECT 'COMMANDS_PASSED';
